// Block (composition) — a mobile/app top navigation bar: leading back button +
// centered title + trailing actions. Contract: docs/rules/block-contract.md.
// Panel posture (full-width; the parent/AppShell owns positioning — no fixed, no
// max-width). Arranges Button + Stack; owns only layout; mints no tokens.
import type { ReactNode, Ref } from "react";
import { ChevronLeft } from "../components/icons";
import { Button } from "../components/Button";
import { Stack } from "../layouts/Stack";
import "./AppBar.css";

export interface AppBarProps {
  /** Centered screen title. */
  title: ReactNode;
  /** When provided, a leading icon-only back button is shown. */
  onBack?: () => void;
  /** Accessible name of the back button, for a screen that is not in English. @default "Back" */
  backLabel?: string;
  /** Trailing actions (buttons / menus) shown at the end. */
  actions?: ReactNode;
  /** Accessible name for the bar landmark. */
  "aria-label"?: string;
  className?: string;
  ref?: Ref<HTMLElement>;
}

export function AppBar({
  title,
  onBack,
  backLabel = "Back",
  actions,
  "aria-label": ariaLabel = "Top bar",
  className,
  ref,
}: AppBarProps) {
  return (
    <Stack
      as="header"
      ref={ref}
      direction="row"
      align="center"
      justify="between"
      gap="small"
      aria-label={ariaLabel}
      className={className ? `sd-appbar ${className}` : "sd-appbar"}
    >
      <div className="sd-appbar__leading">
        {onBack ? (
          <Button variant="ghost" isIconOnly size="small" aria-label={backLabel} onPress={onBack}>
            <ChevronLeft aria-hidden size="1em" />
          </Button>
        ) : null}
      </div>
      <div className="sd-appbar__title sd-type-title-medium">{title}</div>
      <div className="sd-appbar__trailing">{actions}</div>
    </Stack>
  );
}

/* AppBar.css — .sd-appbar (Block)
   Arrangement only: a full-width top bar with three regions (leading · centered
   title · trailing). Leading and trailing share a min-width so the title stays
   optically centered. No look (color/border/surface) — that is a Sys/Component
   concern; this Block owns layout and mints no tokens. */
.sd-appbar {
  width: 100%;
  min-height: var(--sd-control-height-large);
  padding-inline: var(--sd-space-small);
}

.sd-appbar__leading,
.sd-appbar__trailing {
  display: flex;
  align-items: center;
  flex: 0 0 auto;
  min-width: var(--sd-control-height-large);
}

.sd-appbar__trailing {
  justify-content: flex-end;
}

.sd-appbar__title {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  text-align: center;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
